/* Process argc/argv captured by main() before z_main runs, so
   os.args can expose them without threading them through every
   call site. Only emitted when the program references os.args. */
static int z_os_argc_g;
static char** z_os_argv_g;


/* os.args -- copy argv into a freshly-allocated list of strings.
   The caller owns the outer list and every string inside; scope
   exit runs the list destructor which frees each element.

   On Windows the arguments come from the command line itself
   (GetCommandLineW), as UTF-16, split by the rules CommandLineToArgvW
   and the C runtime use: the program name ends at the first space
   outside quotes and takes no escapes; after it, 2n backslashes and a
   quote are n backslashes and a quote that opens or closes quoting,
   2n+1 backslashes and a quote are n backslashes and a literal quote,
   "" inside quotes is a literal quote, and other backslashes are
   literal. */
#if defined(_WIN32)
static void z_os_win_arg(z_t527_t* out, const wchar_t* w, size_t n) {
    size_t un = 0;
    char* u = z_win_utf8(w, (int)n, &un);
    z_t63_t s = z_t63_create((uint64_t)un);
    if (u != NULL) z_t63_append(&s, u, (uint64_t)un);
    free(u);
    z_t527_append(out, s);
}
#endif
static z_t527_t z_os_args(void);
static z_t527_t z_os_args(void) {
#if defined(_WIN32)
    z_t527_t out = z_t527_create((uint64_t)0);
    const wchar_t* c = GetCommandLineW();
    size_t total = wcslen(c);
    wchar_t* cur = (wchar_t*)z_xmalloc((total + 1) * sizeof(wchar_t));
    size_t cn = 0;
    if (*c == 0) {
        wchar_t me[MAX_PATH];
        DWORD got = GetModuleFileNameW(NULL, me, MAX_PATH);
        z_os_win_arg(&out, me, got < MAX_PATH ? got : 0);
    } else {
        int inq = 0;
        for (; *c != 0; c++) {
            if (*c == L'"') {
                inq = !inq;
                continue;
            }
            if (!inq && (*c == L' ' || *c == L'\t')) break;
            cur[cn++] = *c;
        }
        z_os_win_arg(&out, cur, cn);
    }
    while (*c == L' ' || *c == L'\t') c++;
    while (*c != 0) {
        int inq = 0;
        size_t bs = 0;
        cn = 0;
        for (; *c != 0; c++) {
            if (*c == L'\\') {
                bs++;
                continue;
            }
            if (*c == L'"') {
                for (size_t k = 0; k < bs / 2; k++) cur[cn++] = L'\\';
                int literal = (bs % 2) != 0;
                bs = 0;
                if (literal) {
                    cur[cn++] = L'"';
                } else if (inq && c[1] == L'"') {
                    cur[cn++] = L'"';
                    c++;
                } else {
                    inq = !inq;
                }
                continue;
            }
            for (; bs > 0; bs--) cur[cn++] = L'\\';
            if (!inq && (*c == L' ' || *c == L'\t')) break;
            cur[cn++] = *c;
        }
        for (; bs > 0; bs--) cur[cn++] = L'\\';
        z_os_win_arg(&out, cur, cn);
        while (*c == L' ' || *c == L'\t') c++;
    }
    free(cur);
    return out;
#else
    uint64_t n = (uint64_t)(z_os_argc_g > 0 ? z_os_argc_g : 0);
    z_t527_t out = {0};
    out.length = n;
    out.capacity = n;
    if (n > 0) {
        out.data = (z_t63_t*)z_xmalloc(n * sizeof(z_t63_t));
        for (uint64_t i = 0; i < n; i++) {
            out.data[i] = z_t63_new(z_os_argv_g[i]);
        }
    }
    return out;
#endif
}
/* os.get_env -- look up the environment by name (Win32's on Windows,
   where names match regardless of case). Returns
   option.some(string) on hit (copying the value so the caller
   owns the heap buffer and libc's environ isn't aliased); returns
   option.none on miss. `key` is a borrowed view; caller retains. */
static z_t1646_t z_os_env(z_t83_t key);
static z_t1646_t z_os_env(z_t83_t key) {
    z_t1646_t out = {0};
#if defined(_WIN32)
    char* v = z_win_getenv(key.data, key.size);
#else
    char* key_cstr = z_sv_to_cstr(key);
    const char* v = getenv(key_cstr);
    free(key_cstr);
#endif
    if (v == NULL) {
        out.tag = Z_T1646_TAG_0;
        return out;
    }
    z_t63_t* boxed = (z_t63_t*)z_xmalloc(sizeof(z_t63_t));
    *boxed = z_t63_new(v);
#if defined(_WIN32)
    free(v);
#endif
    out.tag = Z_T1646_TAG_1;
    out.data = boxed;
    return out;
}


